import React, { useState, useRef } from "react";
import { Mail, Phone, MapPin, Linkedin, Github, FileText } from "lucide-react";
import emailjs from "@emailjs/browser";

const Contact = () => {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    subject: "",
    message: "",
  });
  const form = useRef();
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState({ message: "", type: "" });

  const handleSubmit = (e) => {
    e.preventDefault();
    setLoading(true);
    setStatus({ message: "", type: "" });

    emailjs
      .sendForm(
        "service_pwhoez6",
        "template_bfk0qmc",
        form.current,
        "dYk8bs0y07ew4C0GN"
      )
      .then(
        (result) => {
          setStatus({
            message: "Message sent successfully!",
            type: "success",
          });
          setFormData({
            name: "",
            email: "",
            subject: "",
            message: "",
          });
        },
        (error) => {
          setStatus({
            message: "Failed to send message. Please try again.",
            type: "error",
          });
        }
      )
      .finally(() => {
        setLoading(false);
      });
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  return (
    <section className="slide-in" id="contact">
      <h2 className="contact-title">Contact Me</h2>
      {/* Contact Info */}
      <div className="contact-card">
        <div className="contact-info-container">
          <div className="contact-info-line">
            <div className="contact-item">
              <Mail className="contact-icon" />
              <a
                href="mailto:maurasweeney8@outlook.com"
                className="contact-link"
              >
                maurasweeney8@outlook.com
              </a>
            </div>
            <div className="contact-item">
              <Phone className="contact-icon" />
              <span>(425) 375-6183</span>
            </div>
            <div className="contact-item">
              <MapPin className="contact-icon" />
              <span>Spokane, WA</span>
            </div>
          </div>
        </div>

        {/* Social Links Line */}
        <div className="social-links">
          <a
            href="https://www.linkedin.com/in/mauraksweeney/"
            className="social-button"
          >
            <Linkedin className="social-icon" />
            <span>LinkedIn</span>
          </a>
          <a href="https://github.com/maurasweeney1" className="social-button">
            <Github className="social-icon" />
            <span>GitHub</span>
          </a>
          <a href="Sweeney-Resume.pdf" className="social-button">
            <FileText className="social-icon" />
            <span>Resume</span>
          </a>
        </div>
      </div>
      {/* Contact Form */}
      <div className="form-card">
        <form ref={form} onSubmit={handleSubmit} className="contact-form">
          <div className="form-group">
            <label htmlFor="name" className="form-label">
              Name
            </label>
            <input
              id="name"
              name="name"
              type="text"
              value={formData.name}
              onChange={handleChange}
              required
              className="form-input"
            />
          </div>

          <div className="form-group">
            <label htmlFor="email" className="form-label">
              Email
            </label>
            <input
              id="email"
              name="email"
              type="email"
              value={formData.email}
              onChange={handleChange}
              required
              className="form-input"
            />
          </div>

          <div className="form-group">
            <label htmlFor="subject" className="form-label">
              Subject
            </label>
            <input
              id="subject"
              name="subject"
              type="text"
              value={formData.subject}
              onChange={handleChange}
              required
              className="form-input"
            />
          </div>

          <div className="form-group">
            <label htmlFor="message" className="form-label">
              Message
            </label>
            <textarea
              id="message"
              name="message"
              value={formData.message}
              onChange={handleChange}
              required
              className="form-textarea"
              rows={4}
            />
          </div>

          {status.message && (
            <div className={`status-message ${status.type}`}>
              {status.message}
            </div>
          )}

          <button type="submit" className="submit-button" disabled={loading}>
            {loading ? "Sending..." : "Send Message"}
          </button>
        </form>
      </div>
    </section>
  );
};

export default Contact;
